/**
 * - `snapshotText` · a check's snapshot as a module: one export, its value as taken
 * - `snapshotRecord` · a snapshot's value read as a record, else an empty one
 */
const snapshotText = (name: string, taken: unknown): string =>
  [
    `// GENERATED by tools/checks.ts: a check's snapshot, as its run took it.`,
    '// Do not edit: a snapshot moves only with a retake the PM accepted.',
    `export const ${name}: unknown = ${JSON.stringify(taken)};`,
    '',
  ].join('\n');

const snapshotRecord = (
  snapshot: unknown,
): Readonly<Record<string, unknown>> =>
  typeof snapshot === 'object' && snapshot !== null && !Array.isArray(snapshot)
    ? Object.fromEntries(Object.entries(snapshot))
    : {};

export { snapshotRecord, snapshotText };
